if (!TOKEN) {
  console.error('Missing BOT_TOKEN env var (see the header of this file).');
  process.exit(1);
}

/** \u9080\u8BF7\u91CC\u7684\u5730\u56FE\uFF1Bbot:state \u672C\u8EAB\u4E0D\u542B\u5730\u56FE\uFF0C\u8FD9\u91CC\u5408\u5E76\u8FDB state.map \u4F9B\u7B56\u7565\u4F7F\u7528 */
